    long ret;
    __asm__ volatile (
        "move $v0, %1\n"
        "syscall\n"
        "move %0, $v0\n"
        : "=r"(ret)
        : "r"(num)
        : "v0", "v1", "a3", "cc", "memory"
    );
    return ret;
}

