#include <string.h>

#define HEAP_SIZE (32 * 1024 * 1024)

static unsigned char __heap[HEAP_SIZE];
static size_t __heap_used = 0;

typedef struct block_header {
    size_t size;
    uint32_t magic;
    struct block_header *next;
    int free;
} block_header_t;

#define BLOCK_MAGIC 0xCAFEBABE
#define BLOCK_HEADER_SIZE 16
#define MIN_BLOCK_SIZE 32

static block_header_t *free_list = NULL;

static void heap_init(void) {
    if (__heap_used == 0) {
        free_list = (block_header_t *)__heap;
        free_list->size = HEAP_SIZE - BLOCK_HEADER_SIZE;
        free_list->magic = BLOCK_MAGIC;
        free_list->next = NULL;
        free_list->free = 1;
        __heap_used = 1;
    }
}

void *malloc(size_t size) {
    heap_init();

    if (size == 0) return NULL;

    size = (size + 7) & ~7;

    block_header_t *curr = free_list;
    block_header_t *prev = NULL;

    while (curr != NULL) {
        if (curr->free && curr->size >= size + BLOCK_HEADER_SIZE) {
            if (curr->size > size + BLOCK_HEADER_SIZE + MIN_BLOCK_SIZE) {
                block_header_t *new_block = (block_header_t *)((char *)curr + BLOCK_HEADER_SIZE + size);
                new_block->size = curr->size - size - BLOCK_HEADER_SIZE;
                new_block->magic = BLOCK_MAGIC;
                new_block->free = 1;
                new_block->next = curr->next;

                curr->size = size;
                curr->next = new_block;
            }
            curr->free = 0;
            return (void *)((char *)curr + BLOCK_HEADER_SIZE);
        }
        prev = curr;
        curr = curr->next;
    }

    return NULL;
}

void *calloc(size_t nmemb, size_t size) {
    size_t total = nmemb * size;
    if (total == 0) return NULL;
    void *ptr = malloc(total);
    if (ptr) {
        memset(ptr, 0, total);
    }
    return ptr;
}

void *realloc(void *ptr, size_t size) {
    if (ptr == NULL) return malloc(size);
    if (size == 0) {
        free(ptr);
        return NULL;
    }

    block_header_t *header = (block_header_t *)((char *)ptr - BLOCK_HEADER_SIZE);
    if (header->magic != BLOCK_MAGIC) return NULL;

    if (header->size >= size) {
        return ptr;
    }

    void *new_ptr = malloc(size);
    if (new_ptr == NULL) return NULL;

    size_t copy_size = (header->size < size) ? header->size : size;
    memcpy(new_ptr, ptr, copy_size);
    free(ptr);

    return new_ptr;
}

void free(void *ptr) {
    if (ptr == NULL) return;

    block_header_t *header = (block_header_t *)((char *)ptr - BLOCK_HEADER_SIZE);
    if (header->magic != BLOCK_MAGIC) return;

    header->free = 1;

    block_header_t *curr = free_list;
    while (curr != NULL) {
        if (curr->free && curr->next != NULL && curr->next->free) {
            curr->size += BLOCK_HEADER_SIZE + curr->next->size;
            curr->next = curr->next->next;
            continue;
        }
        curr = curr->next;
    }
}

