struct __my_file {
    int     fd;
    int     error;
    int     eof;
    char   *buf;
    size_t  buf_size;
    size_t  buf_pos;
    size_t  buf_len;
    int     has_buf;
    char    path[256];
    char    mode[8];
};

#define MAX_FILES 16
static FILE __files[MAX_FILES];
static int __files_inited = 0;

static void init_files(void) {
    if (__files_inited) return;
    for (int i = 0; i < MAX_FILES; i++) {
        __files[i].fd = -1;
        __files[i].error = 0;
        __files[i].eof = 0;
        __files[i].buf = NULL;
        __files[i].buf_size = 0;
        __files[i].buf_pos = 0;
        __files[i].buf_len = 0;
        __files[i].has_buf = 0;
        __files[i].path[0] = '\0';
        __files[i].mode[0] = '\0';
    }
    __files[0].fd = 0;
    __files[1].fd = 1;
    __files[2].fd = 2;
    __files[0].mode[0] = 'r';
    __files[1].mode[0] = 'w';
    __files[2].mode[0] = 'w';
    __files_inited = 1;
}

FILE *stdin  = &__files[0];
FILE *stdout = &__files[1];
FILE *stderr = &__files[2];

static int mode_to_flags(const char *mode) {
    int flags = 0;
    int plus = 0;
    if (strchr(mode, '+')) plus = 1;
    if (strchr(mode, 'b')) plus = plus;

    if (mode[0] == 'r') {
        flags = 0;
        if (plus) flags |= 2;
    } else if (mode[0] == 'w') {
        flags = 1 | 64 | 512;
        if (plus) flags = 2 | 64 | 512;
    } else if (mode[0] == 'a') {
        flags = 1 | 64 | 1024;
        if (plus) flags = 2 | 64 | 1024;
    }
    return flags;
}

FILE *fopen(const char *path, const char *mode) {
    init_files();
    if (path == NULL || mode == NULL) return NULL;

    int slot = -1;
    for (int i = 3; i < MAX_FILES; i++) {
        if (__files[i].fd < 0) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {
        errno = EMFILE;
        return NULL;
    }

    int flags = mode_to_flags(mode);
    long fd = my_syscall3(SYS_open, (long)path, flags, 0644);
    if (fd < 0) {
        errno = EACCES;
        return NULL;
    }

    __files[slot].fd = (int)fd;
    __files[slot].error = 0;
    __files[slot].eof = 0;
    strncpy(__files[slot].path, path, sizeof(__files[slot].path) - 1);
    __files[slot].path[sizeof(__files[slot].path) - 1] = '\0';
    strncpy(__files[slot].mode, mode, sizeof(__files[slot].mode) - 1);
    __files[slot].mode[sizeof(__files[slot].mode) - 1] = '\0';

    return &__files[slot];
}

int fclose(FILE *stream) {
    if (stream == NULL) return EOF;
    if (stream->fd >= 3) {
        my_syscall1(SYS_close, stream->fd);
        stream->fd = -1;
    }
    return 0;
}

int fflush(FILE *stream) {
    (void)stream;
    return 0;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    if (stream == NULL || ptr == NULL || size == 0 || nmemb == 0) return 0;

    size_t total = size * nmemb;
    size_t got = 0;
    while (got < total) {
        long n = my_syscall3(SYS_read, stream->fd,
                             (long)((char *)ptr + got),
                             total - got);
        if (n <= 0) {
            stream->eof = (n == 0) ? 1 : stream->eof;
            if (n < 0) stream->error = 1;
            break;
        }
        got += n;
    }
    return got / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *stream) {
    if (stream == NULL || ptr == NULL || size == 0 || nmemb == 0) return 0;

    size_t total = size * nmemb;
    size_t written = 0;
    while (written < total) {
        long n = my_syscall3(SYS_write, stream->fd,
                             (long)((const char *)ptr + written),
                             total - written);
        if (n <= 0) {
            stream->error = (n < 0) ? 1 : stream->error;
            break;
        }
        written += n;
    }
    return written / size;
}

int fseek(FILE *stream, long offset, int whence) {
    if (stream == NULL) return -1;
    long pos = my_syscall3(SYS_lseek, stream->fd, offset, whence);
    if (pos < 0) {
        stream->error = 1;
        return -1;
    }
    stream->eof = 0;
    return 0;
}

long ftell(FILE *stream) {
    if (stream == NULL) return -1;
    long pos = my_syscall3(SYS_lseek, stream->fd, 0, 1);
    return pos;
}

void rewind(FILE *stream) {
    if (stream) {
        fseek(stream, 0, 0);
        stream->error = 0;
        stream->eof = 0;
    }
}

int feof(FILE *stream) {
    return stream ? stream->eof : 0;
}

int ferror(FILE *stream) {
    return stream ? stream->error : 0;
}

void clearerr(FILE *stream) {
    if (stream) {
        stream->eof = 0;
        stream->error = 0;
    }
}

int fgetc(FILE *stream) {
    if (stream == NULL) return EOF;
    unsigned char c;
    long n = my_syscall3(SYS_read, stream->fd, (long)&c, 1);
    if (n <= 0) {
        stream->eof = (n == 0) ? 1 : stream->eof;
        return EOF;
    }
    return (int)c;
}

int getc(FILE *stream) {
    return fgetc(stream);
}

char *fgets(char *s, int size, FILE *stream) {
    if (s == NULL || stream == NULL || size <= 0) return NULL;
    int i = 0;
    while (i < size - 1) {
        int c = fgetc(stream);
        if (c == EOF) {
            if (i == 0) return NULL;
            break;
        }
        s[i++] = (char)c;
        if (c == '\n') break;
    }
    s[i] = '\0';
    return s;
}

int fputc(int c, FILE *stream) {
    if (stream == NULL) return EOF;
    unsigned char ch = (unsigned char)c;
    long n = my_syscall3(SYS_write, stream->fd, (long)&ch, 1);
    if (n <= 0) {
        stream->error = 1;
        return EOF;
    }
    return c;
}

int putc(int c, FILE *stream) {
    return fputc(c, stream);
}

int fputs(const char *s, FILE *stream) {
    if (s == NULL || stream == NULL) return EOF;
    size_t len = strlen(s);
    size_t n = fwrite(s, 1, len, stream);
    return n == len ? 0 : EOF;
}

int putchar(int c) {
    return fputc(c, stdout);
}

int puts(const char *s) {
    if (s == NULL) return EOF;
    int r = fputs(s, stdout);
    if (r == EOF) return EOF;
    if (fputc('\n', stdout) == EOF) return EOF;
    return 0;
}

int getchar(void) {
    return fgetc(stdin);
}

char *gets(char *s) {
    if (s == NULL) return NULL;
    int i = 0;
    while (1) {
        int c = fgetc(stdin);
        if (c == EOF || c == '\n') break;
        s[i++] = (char)c;
    }
    s[i] = '\0';
    return i > 0 ? s : NULL;
}

int remove(const char *pathname) {
    if (pathname == NULL) return -1;
    long r = my_syscall1(SYS_unlink, (long)pathname);
    return r < 0 ? -1 : 0;
}

int rename(const char *oldpath, const char *newpath) {
    if (oldpath == NULL || newpath == NULL) return -1;
    long r = my_syscall3(SYS_rename, (long)oldpath, (long)newpath, 0);
    return r < 0 ? -1 : 0;
}

static char __print_buf[1024];

static int write_to_stream(FILE *stream, const char *buf, size_t len) {
    if (stream == NULL) return -1;
    return (int)fwrite(buf, 1, len, stream);
}

static int format_int(char *buf, long value, int base, int is_signed, int width, int zero_pad, int left_align, int precision) {
    char tmp[64];
    char *p = tmp + sizeof(tmp) - 1;
    int len = 0;
    int negative = 0;
    unsigned long uvalue;

    if (is_signed && value < 0) {
        negative = 1;
        uvalue = (unsigned long)(-(value + 1)) + 1;
    } else {
        uvalue = (unsigned long)value;
    }

    if (uvalue == 0) {
        *--p = '0';
        len = 1;
    } else {
        while (uvalue > 0) {
            int digit = uvalue % base;
            *--p = (digit < 10) ? ('0' + digit) : ('a' + digit - 10);
            uvalue /= base;
            len++;
        }
    }

    int total = len + (negative ? 1 : 0);
    int pad = width - total;
    if (pad < 0) pad = 0;

    int written = 0;
    if (pad > 0 && !left_align && zero_pad) {
        if (negative) {
            buf[written++] = '-';
            negative = 0;
        }
        for (int i = 0; i < pad; i++) buf[written++] = '0';
    } else if (pad > 0 && !left_align) {
        for (int i = 0; i < pad; i++) buf[written++] = ' ';
    }

    if (negative) buf[written++] = '-';

    for (int i = 0; i < len; i++) {
        buf[written++] = p[i];
    }

    if (pad > 0 && left_align) {
        for (int i = 0; i < pad; i++) buf[written++] = ' ';
    }

    return written;
}

static int format_uint(char *buf, unsigned long value, int base, int is_upper, int width, int zero_pad, int left_align) {
    char tmp[64];
    char *p = tmp + sizeof(tmp) - 1;
    int len = 0;

    if (value == 0) {
        *--p = '0';
        len = 1;
    } else {
        while (value > 0) {
            int digit = value % base;
            *--p = is_upper
                ? (digit < 10 ? '0' + digit : 'A' + digit - 10)
                : (digit < 10 ? '0' + digit : 'a' + digit - 10);
            value /= base;
            len++;
        }
    }

    int total = len;
    int pad = width - total;
    if (pad < 0) pad = 0;

    int written = 0;
    if (pad > 0 && !left_align && zero_pad) {
        for (int i = 0; i < pad; i++) buf[written++] = '0';
    } else if (pad > 0 && !left_align) {
        for (int i = 0; i < pad; i++) buf[written++] = ' ';
    }

    for (int i = 0; i < len; i++) {
        buf[written++] = p[i];
    }

    if (pad > 0 && left_align) {
        for (int i = 0; i < pad; i++) buf[written++] = ' ';
    }

    return written;
}

static int format_string(char *buf, const char *s, int width, int left_align, int precision) {
    int len = 0;
    if (s == NULL) s = "(null)";
    int slen = strlen(s);
    if (precision >= 0 && slen > precision) slen = precision;

    int pad = width - slen;
    if (pad < 0) pad = 0;

    int written = 0;
    if (pad > 0 && !left_align) {
        for (int i = 0; i < pad; i++) buf[written++] = ' ';
    }
    for (int i = 0; i < slen; i++) buf[written++] = s[i];
    if (pad > 0 && left_align) {
        for (int i = 0; i < pad; i++) buf[written++] = ' ';
    }
    return written;
}

static int vformat_to(FILE *stream, const char *format, va_list ap) {
    int total = 0;
    char num_buf[64];
    const char *p = format;

    while (*p) {
        if (*p != '%') {
            char ch = *p++;
            write_to_stream(stream, &ch, 1);
            total++;
            continue;
        }

        p++;

        int left_align = 0;
        int zero_pad = 0;
        int has_precision = 0;
        int precision = -1;
        int width = 0;

        if (*p == '-') { left_align = 1; p++; }
        if (*p == '0') { zero_pad = 1; p++; }
        while (*p >= '0' && *p <= '9') {
            width = width * 10 + (*p - '0');
            p++;
        }
        if (*p == '.') {
            p++;
            has_precision = 1;
            precision = 0;
            while (*p >= '0' && *p <= '9') {
                precision = precision * 10 + (*p - '0');
                p++;
            }
        }

        int modifier = 0;
        if (*p == 'l') {
            modifier = 1;
            p++;
            if (*p == 'l') {
                modifier = 2;
                p++;
            }
        } else if (*p == 'h') {
            modifier = -1;
            p++;
        }

        int written = 0;
        switch (*p) {
            case 'd':
            case 'i': {
                long val;
                if (modifier == 2) val = (long)va_arg(ap, long long);
                else if (modifier == 1) val = va_arg(ap, long);
                else val = va_arg(ap, int);
                written = format_int(num_buf, val, 10, 1, width, zero_pad, left_align, precision);
                write_to_stream(stream, num_buf, written);
                break;
            }
            case 'u': {
                unsigned long val;
                if (modifier == 2) val = (unsigned long)va_arg(ap, unsigned long long);
                else if (modifier == 1) val = va_arg(ap, unsigned long);
                else val = va_arg(ap, unsigned int);
                written = format_uint(num_buf, val, 10, 0, width, zero_pad, left_align);
                write_to_stream(stream, num_buf, written);
                break;
            }
            case 'x': {
                unsigned long val;
                if (modifier == 2) val = (unsigned long)va_arg(ap, unsigned long long);
                else if (modifier == 1) val = va_arg(ap, unsigned long);
                else val = va_arg(ap, unsigned int);
                written = format_uint(num_buf, val, 16, 0, width, zero_pad, left_align);
                write_to_stream(stream, num_buf, written);
                break;
            }
            case 'X': {
                unsigned long val;
                if (modifier == 2) val = (unsigned long)va_arg(ap, unsigned long long);
                else if (modifier == 1) val = va_arg(ap, unsigned long);
                else val = va_arg(ap, unsigned int);
                written = format_uint(num_buf, val, 16, 1, width, zero_pad, left_align);
                write_to_stream(stream, num_buf, written);
                break;
            }
            case 'o': {
