                double frac = val - (double)whole;
                n = format_uint(tmp, whole, 10, 0, 0, 0, 0);
                write_to_stream(stream, tmp, n);
                write_to_stream(stream, ".", 1);
                for (int i = 0; i < 6; i++) {
