static int isspace_local(int c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

unsigned long strtoul_internal(const char *nptr, char **endptr, int base, int *negative) {
    const char *p = nptr;
    unsigned long result = 0;
    int neg = 0;
    int any = 0;

    while (isspace_local((unsigned char)*p)) p++;

    if (*p == '+' || *p == '-') {
        if (*p == '-') neg = 1;
        p++;
    }

    if ((base == 0 || base == 16) && *p == '0' && (p[1] == 'x' || p[1] == 'X')) {
        p += 2;
        base = 16;
    }

    if (base == 0) {
        if (*p == '0') base = 8;
        else base = 10;
    }

    int v;
    while ((v = *p) != 0) {
        if (v >= '0' && v <= '9') v -= '0';
        else if (v >= 'a' && v <= 'z') v = v - 'a' + 10;
        else if (v >= 'A' && v <= 'Z') v = v - 'A' + 10;
        else break;

        if (v >= base) break;
        result = result * base + v;
        any = 1;
        p++;
    }

    if (endptr) *endptr = (char *)(any ? p : nptr);
    if (negative) *negative = neg;
    return result;
}

long strtol(const char *nptr, char **endptr, int base) {
    int neg = 0;
    unsigned long r = strtoul_internal(nptr, endptr, base, &neg);
    if (neg) return -(long)r;
    return (long)r;
}

long long strtoll(const char *nptr, char **endptr, int base) {
    int neg = 0;
    unsigned long r = strtoul_internal(nptr, endptr, base, &neg);
    if (neg) return -(long long)r;
    return (long long)r;
}

unsigned long strtoul(const char *nptr, char **endptr, int base) {
    return strtoul_internal(nptr, endptr, base, NULL);
}

