    return (unsigned long long)strtoul_internal(nptr, endptr, base, NULL);
}

double strtod(const char *nptr, char **endptr) {
    double result = 0.0;
    double divisor = 1.0;
    int negative = 0;
    int has_digits = 0;
    const char *p = nptr;

    while (isspace_local((unsigned char)*p)) p++;

    if (*p == '+' || *p == '-') {
        if (*p == '-') negative = 1;
        p++;
    }

    while (*p >= '0' && *p <= '9') {
        result = result * 10.0 + (*p - '0');
        p++;
        has_digits = 1;
    }

    if (*p == '.') {
        p++;
        while (*p >= '0' && *p <= '9') {
            result = result * 10.0 + (*p - '0');
            divisor *= 10.0;
            p++;
            has_digits = 1;
        }
    }

    result /= divisor;
    if (negative) result = -result;

    if (endptr) *endptr = (char *)(has_digits ? p : nptr);
    return result;
}

