static char *env_table[64] = {NULL};

char *getenv(const char *name) {
    if (name == NULL) return NULL;
    for (int i = 0; i < 64; i++) {
        if (env_table[i] == NULL) break;
        const char *eq = strchr(env_table[i], '=');
        if (eq == NULL) continue;
        size_t namelen = eq - env_table[i];
        if (strncmp(env_table[i], name, namelen) == 0 && name[namelen] == '\0') {
            return (char *)(eq + 1);
        }
    }
    return NULL;
}

int setenv(const char *name, const char *value, int overwrite) {
    if (name == NULL || value == NULL) return -1;
    if (!overwrite && getenv(name) != NULL) return 0;
    for (int i = 0; i < 64; i++) {
        if (env_table[i] == NULL) {
            size_t len = strlen(name) + strlen(value) + 2;
            char *entry = (char *)malloc(len);
            if (!entry) return -1;
            strcpy(entry, name);
            strcat(entry, "=");
            strcat(entry, value);
            env_table[i] = entry;
            return 0;
        }
    }
    return -1;
}

int unsetenv(const char *name) {
    if (name == NULL) return -1;
    for (int i = 0; i < 64; i++) {
        if (env_table[i] == NULL) break;
        const char *eq = strchr(env_table[i], '=');
        if (eq == NULL) continue;
        size_t namelen = eq - env_table[i];
        if (strncmp(env_table[i], name, namelen) == 0 && name[namelen] == '\0') {
            free(env_table[i]);
            for (int j = i; j < 63; j++) {
                env_table[j] = env_table[j+1];
            }
            env_table[63] = NULL;
            return 0;
        }
    }
    return 0;
}

int putenv(char *string) {
    if (string == NULL) return -1;
    char *eq = strchr(string, '=');
    if (eq == NULL) return -1;
    *eq = '\0';
    int ret = setenv(string, eq + 1, 1);
    *eq = '=';
    return ret;
}

