struct tm *gmtime(const time_t *timep) {
    static struct tm tm_buf;
    time_t t = *timep;
    tm_buf.tm_sec = t % 60; t /= 60;
    tm_buf.tm_min = t % 60; t /= 60;
    tm_buf.tm_hour = t % 24; t /= 24;
    t += 719468;
    int era = (t >= 0 ? t : t - 146096) / 146097;
    int doe = t - era * 146097;
    int yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    int y = yoe + era * 400;
    int doy = doe - (365*yoe + yoe/4 - yoe/100);
    int mp = (5*doy + 2)/153;
    tm_buf.tm_mday = doy - (153*mp+2)/5 + 1;
    tm_buf.tm_mon = (mp < 10 ? mp+3 : mp-9);
    if (tm_buf.tm_mon < 2) y++;
    tm_buf.tm_year = y - 1900;
    tm_buf.tm_wday = 0;
    tm_buf.tm_yday = 0;
    tm_buf.tm_isdst = 0;
    return &tm_buf;
}

