char *asctime(const struct tm *tm) {
    static char buf[26];
    const char *days[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};
    const char *mons[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
    int d = tm->tm_mday;
    int H = tm->tm_hour;
    int M = tm->tm_min;
    int S = tm->tm_sec;
    int Y = tm->tm_year + 1900;

    int pos = 0;
    const char *day = days[tm->tm_wday % 7];
    for (int i = 0; i < 3; i++) buf[pos++] = day[i];
    buf[pos++] = ' ';
    const char *mon = mons[tm->tm_mon % 12];
    for (int i = 0; i < 3; i++) buf[pos++] = mon[i];
    buf[pos++] = ' ';
    if (d < 10) { buf[pos++] = ' '; buf[pos++] = '0' + d; }
    else if (d < 20) { buf[pos++] = '1'; buf[pos++] = '0' + (d - 10); }
    else if (d < 30) { buf[pos++] = '2'; buf[pos++] = '0' + (d - 20); }
    else { buf[pos++] = '3'; buf[pos++] = '0' + (d - 30); }
    buf[pos++] = ' ';
    buf[pos++] = '0' + (H / 10);
    buf[pos++] = '0' + (H % 10);
    buf[pos++] = ':';
    buf[pos++] = '0' + (M / 10);
    buf[pos++] = '0' + (M % 10);
    buf[pos++] = ':';
    buf[pos++] = '0' + (S / 10);
    buf[pos++] = '0' + (S % 10);
    buf[pos++] = ' ';
    buf[pos++] = '0' + (Y / 1000); Y %= 1000;
    buf[pos++] = '0' + (Y / 100); Y %= 100;
    buf[pos++] = '0' + (Y / 10);
    buf[pos++] = '0' + (Y % 10);
    buf[pos++] = '\n';
    buf[pos] = '\0';
    return buf;
}

