static double my_pow_int(double x, int n) {
    double r = 1.0;
    int neg = 0;
    if (n < 0) { neg = 1; n = -n; }
    while (n > 0) {
        if (n & 1) r *= x;
        x *= x;
        n >>= 1;
    }
    return neg ? 1.0 / r : r;
}

double fabs(double x) {
