double log(double x) {
    if (x <= 0) return 0;
    if (x == 1) return 0;
    int k = 0;
    while (x >= 2) { x /= 2; k++; }
    while (x < 0.5) { x *= 2; k--; }
    double z = x - 1;
    double r = 0;
    double term = z;
    int sign = 1;
    for (int i = 1; i < 50; i++) {
        r += sign * term / i;
        term *= z;
        sign = -sign;
        if (my_fabs(term / i) < 1e-15) break;
    }
    return r + k * 0.6931471805599453;
}

