double asin(double x) {
    if (x < -1 || x > 1) return 0;
    if (x == 1) return 1.5707963267948966;
    if (x == -1) return -1.5707963267948966;
    double r = x;
    double term = x;
    for (int i = 1; i < 30; i++) {
        term *= x * x * (2.0 * i - 1) / (2.0 * i * (2.0 * i + 1));
        r += term;
