#include <setjmp.h>

typedef struct {
    int  __fp_regs[8];
    int  __gp_regs[8];
    int  __sp;
    int  __fp;
    int  __ra;
    int  __s0, __s1, __s2, __s3, __s4, __s5, __s6, __s7;
} jmp_buf_full;

int setjmp(jmp_buf env) {
    jmp_buf_full *j = (jmp_buf_full *)env;
    int *fp = (int *)__builtin_frame_address(0);
    int *gp = (int *)__builtin_frame_address(0);
    int i;

    (void)fp; (void)gp;
    for (i = 0; i < 8; i++) {
        j->__fp_regs[i] = 0;
        j->__gp_regs[i] = 0;
    }

    __asm__ volatile (
        "sw $sp, %0\n"
        "sw $ra, %1\n"
        : "+m"(j->__sp), "+m"(j->__ra)
    );

    __asm__ volatile (
        "sw $s0, %0\n"
        "sw $s1, %1\n"
        "sw $s2, %2\n"
        "sw $s3, %3\n"
        "sw $s4, %4\n"
        "sw $s5, %5\n"
        "sw $s6, %6\n"
        "sw $s7, %7\n"
        : "+m"(j->__s0), "+m"(j->__s1), "+m"(j->__s2), "+m"(j->__s3),
          "+m"(j->__s4), "+m"(j->__s5), "+m"(j->__s6), "+m"(j->__s7)
    );

    return 0;
}

void longjmp(jmp_buf env, int val) {
    jmp_buf_full *j = (jmp_buf_full *)env;

    __asm__ volatile (
        "lw $s0, %0\n"
        "lw $s1, %1\n"
        "lw $s2, %2\n"
        "lw $s3, %3\n"
        "lw $s4, %4\n"
        "lw $s5, %5\n"
        "lw $s6, %6\n"
        "lw $s7, %7\n"
        : : "m"(j->__s0), "m"(j->__s1), "m"(j->__s2), "m"(j->__s3),
            "m"(j->__s4), "m"(j->__s5), "m"(j->__s6), "m"(j->__s7)
    );

    int new_sp = j->__sp;
    int new_ra = j->__ra;

    __asm__ volatile (
        "move $sp, %0\n"
        "move $ra, %1\n"
        :
        : "r"(new_sp), "r"(new_ra)
    );

    if (val == 0) val = 1;

    int ret_addr = new_ra;
    (void)ret_addr;

    __builtin_unreachable();
}

